package net.battlespades.bot;
import java.util.*;
import java.util.function.ToIntFunction;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.RecoveryPlanning.World;
import static net.battlespades.bot.ProjectSites.Column;

/** Bounded support/approach floods and minimum vertex cuts using the authoritative 18-neighbour grounding rule. */
public final class StructureCollapse {
    private StructureCollapse(){}
    static final int INF=1<<30;static final int[][] FACES=SchematicPlanning.FACES,CARDINAL=SchematicPlanning.CARDINAL;
    static final List<Cell> NEIGHBORS;static{var n=new ArrayList<Cell>();for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++){int sum=Math.abs(x)+Math.abs(y)+Math.abs(z);if(sum>=1&&sum<=2)n.add(new Cell(x,y,z));}NEIGHBORS=List.copyOf(n);}
    static final Comparator<Cell> CELLS=SchematicPlanning.CELLS;
    public record Plan(List<Cell> support,List<Cell> cut,List<Cell> sites,int cost,int falling,int explored){public Plan{support=List.copyOf(support);cut=List.copyOf(cut);sites=List.copyOf(sites);}}
    public record Isolation(boolean isolated,int standingCells,int supportZ){}
    public static List<Cell> support(World w,Vector p){int expected=(int)Math.rint(p.z()+2.25);var columns=new TreeSet<Column>(Comparator.comparingInt(Column::x).thenComparingInt(Column::y));for(double x:new double[]{-.45,.45})for(double y:new double[]{-.45,.45})columns.add(new Column((int)Math.floor(p.x()+x),(int)Math.floor(p.y()+y)));for(int dz:new int[]{0,1,-1,2,3}){int level=expected+dz;if(level<0||level>239)continue;var cells=new ArrayList<Cell>();for(var c:columns)if(c.x()>=0&&c.x()<512&&c.y()>=0&&c.y()<512&&w.solid(c.x(),c.y(),level))cells.add(new Cell(c.x(),c.y(),level));if(!cells.isEmpty())return List.copyOf(cells);}return List.of();}
    static boolean stand(World w,int x,int y,int z){return x>=0&&x<512&&y>=0&&y<512&&w.solid(x,y,z)&&!w.solid(x,y,z-1)&&!w.solid(x,y,z-2);}
    public static final class IsolationJob {
        private final Thread owner=Thread.currentThread();private final World world;private final List<Cell> hunters;private final int limit,floor;private final double radius;private final Set<Cell> seen=new HashSet<>();private final ArrayDeque<Cell> queue=new ArrayDeque<>();private Isolation result;
        public IsolationJob(World world,Vector p,List<Vector> hunters,int limit,double radius){this.world=world;this.limit=limit;this.radius=radius;this.hunters=hunters.stream().map(h->new Cell((int)Math.floor(h.x()),(int)Math.floor(h.y()),(int)Math.rint(h.z()+2.25))).toList();var support=support(world,p);floor=support.isEmpty()?(int)Math.rint(p.z()+2.25):support.getFirst().z();if(support.isEmpty())result=new Isolation(false,0,floor);else{seen.add(support.getFirst());queue.add(support.getFirst());}}
        public boolean advance(int work){if(Thread.currentThread()!=owner)throw new IllegalStateException("Structural search outside owner");while(result==null&&work-->0){if(queue.isEmpty()){result=new Isolation(true,seen.size(),floor);break;}var n=queue.removeFirst();if(hunters.stream().anyMatch(h->h.equals(n)||Math.abs(h.x()-n.x())<=radius&&Math.abs(h.y()-n.y())<=radius&&Math.abs(h.z()-n.z())<=1)){result=new Isolation(false,seen.size(),floor);break;}for(var d:CARDINAL){int x=n.x()+d[0],y=n.y()+d[1];for(int z:new int[]{n.z(),n.z()-1,n.z()+1}){var c=new Cell(x,y,z);if(seen.contains(c)||z==n.z()-1&&world.solid(n.x(),n.y(),n.z()-3))continue;if(stand(world,x,y,z)){seen.add(c);queue.add(c);break;}}}if(seen.size()>limit)result=new Isolation(false,seen.size(),floor);}return result!=null;}public Isolation result(){return result;}}
    public record Approach(int supportZ,Map<Cell,Integer> steps,boolean closed,int frontier,double radius,Map<Cell,Cell> toward,Map<Column,List<Cell>> squares){public Approach{steps=Collections.unmodifiableMap(new LinkedHashMap<>(steps));toward=Map.copyOf(toward);var s=new LinkedHashMap<Column,List<Cell>>();squares.forEach((k,v)->s.put(k,List.copyOf(v)));squares=Collections.unmodifiableMap(s);}public Cell cellAt(Vector p){int x=(int)Math.floor(p.x()),y=(int)Math.floor(p.y()),floor=(int)Math.rint(p.z()+2.25);for(int z:new int[]{floor,floor+1,floor-1}){var c=new Cell(x,y,z);if(steps.containsKey(c))return c;}return null;}public Integer movesFrom(Vector p){var c=cellAt(p);return c==null?null:steps.get(c);}public Cell waypoint(Cell cell,int ahead){for(int i=0;i<Math.max(0,ahead);i++){var next=toward.get(cell);if(next==null)break;cell=next;}return cell;}public Cell entryNear(Vector p,double reach){int floor=(int)Math.rint(p.z()+2.25),sx=(int)Math.floor(p.x())>>3,sy=(int)Math.floor(p.y())>>3;Cell best=null;double gap=reach*reach;for(int ring=0;ring<(int)reach/8+2;ring++){if(best!=null&&gap<=64.*(ring-1)*(ring-1))break;for(int x=-ring;x<=ring;x++){boolean edge=Math.abs(x)==ring;var offsets=new ArrayList<Integer>();if(edge)for(int y=-ring;y<=ring;y++)offsets.add(y);else{offsets.add(-ring);offsets.add(ring);}for(int y:offsets)for(var c:squares.getOrDefault(new Column(sx+x,sy+y),List.of())){if(Math.abs(c.z()-floor)>2)continue;double dx=c.x()+.5-p.x(),dy=c.y()+.5-p.y(),g=dx*dx+dy*dy;if(g<gap){gap=g;best=c;}}}}return best;}}
    private record Scan(boolean[] cells,List<Integer> levels){}
    public static final class ApproachJob {
        private final Thread owner=Thread.currentThread();private final World world;private final Vector position;private final int limit,jump,drop,floor;private final LinkedHashMap<Cell,Integer> steps=new LinkedHashMap<>();private final LinkedHashMap<Cell,Cell> toward=new LinkedHashMap<>();private final ArrayDeque<Cell> queue=new ArrayDeque<>();private final Map<Cell,Scan> scans=new HashMap<>();private double radius;private int frontier;private boolean done;private Approach result;
        public ApproachJob(World world,Vector p,int limit,int jump,int drop){this.world=world;position=p;this.limit=limit;this.jump=jump;this.drop=drop;var support=support(world,p);floor=support.isEmpty()?0:support.getFirst().z();for(var c:support){steps.put(c,0);queue.add(c);}done=support.isEmpty();}
        Scan scan(int x,int y,int z){return scans.computeIfAbsent(new Cell(x,y,z),key->{var column=new boolean[drop+3+jump+1];for(int o=-drop-3;o<=jump;o++)column[drop+3+o]=z+o>=0&&world.solid(x,y,z+o);var levels=new ArrayList<Integer>();for(int o=-drop;o<=jump;o++)if(column[drop+3+o]&&!column[drop+2+o]&&!column[drop+1+o])levels.add(o);return new Scan(column,levels);});}
        public boolean advance(int work){if(Thread.currentThread()!=owner)throw new IllegalStateException("Structural search outside owner");while(!done&&work-->0){if(queue.isEmpty()){finish();break;}var c=queue.removeFirst();int depth=steps.get(c);if(steps.size()>=limit){frontier=depth;finish();break;}radius=Math.max(radius,Math.hypot(c.x()+.5-position.x(),c.y()+.5-position.y()));boolean[] own=null;for(var d:CARDINAL){int x=c.x()+d[0],y=c.y()+d[1];if(x<0||x>=512||y<0||y>=512)continue;var scan=scan(x,y,c.z());for(int offset:scan.levels()){int z=c.z()+offset;var key=new Cell(x,y,z);if(steps.containsKey(key)||z>239)continue;boolean blocked=false;if(offset>=1){for(int k=-2;k<offset-2;k++)blocked|=scan.cells()[drop+3+k];}else if(offset<=-1){if(own==null)own=scan(c.x(),c.y(),c.z()).cells();int top=offset==-1?offset-2:offset-3;for(int k=top;k<-2;k++)blocked|=own[drop+3+k];}if(blocked)continue;steps.put(key,depth+1);toward.put(key,c);queue.add(key);}}}return done;}
        void finish(){done=true;var squares=new LinkedHashMap<Column,List<Cell>>();for(var c:steps.keySet())squares.computeIfAbsent(new Column(c.x()>>3,c.y()>>3),k->new ArrayList<>()).add(c);result=new Approach(floor,steps,queue.isEmpty()&&frontier==0,frontier,radius,toward,squares);}public Approach result(){return result;}}
    static Integer floorBelow(World w,int x,int y,int z,int depth){for(int level=z;level<=Math.min(z+depth,239);level++)if(w.solid(x,y,level))return level;return null;}
    public static int digCost(World w,Cell c,Integer ground){if(c.z()>238)return INF;int best=25;for(var d:FACES){int x=c.x()+d[0],y=c.y()+d[1],z=c.z()+d[2];if(x<0||x>=512||y<0||y>=512||z<0||w.solid(x,y,z))continue;var floor=floorBelow(w,x,y,z,4);if(floor==null||ground!=null&&floor<ground-2)continue;int height=floor-c.z();if(height>3)continue;best=Math.min(best,height<=1?1:2);if(best==1)break;}if(best==25&&ground!=null&&ground-c.z()>=-1&&ground-c.z()<=2)best=2;return best;}
    public static int hordeFloor(World w,Vector p,List<Vector> hunters,double radius){int start=(int)Math.rint(p.z()+2.25);var samples=new ArrayList<Integer>();for(var h:hunters){if(BotVectors.flat(h,p)>radius)continue;int feet=(int)Math.rint(h.z()+2.25),x=(int)Math.floor(h.x()),y=(int)Math.floor(h.y());Integer under=x>=0&&x<512&&y>=0&&y<512&&feet>=1?floorBelow(w,x,y,feet-1,6):null;samples.add(under==null?feet:under);}for(int ring:new int[]{6,10})for(int step=0;step<8;step++){double angle=step*Math.PI/4;int x=(int)Math.floor(p.x()+ring*Math.cos(angle)),y=(int)Math.floor(p.y()+ring*Math.sin(angle));if(x<0||x>=512||y<0||y>=512)continue;var floor=floorBelow(w,x,y,start,239-start);samples.add(floor==null?239:floor);}if(samples.isEmpty())return start;Collections.sort(samples);return samples.get(3*samples.size()/4);}
    /** Each advance processes bounded flood/graph nodes and retains all residual flow state. */
    public static final class CutJob {
        private final Thread owner=Thread.currentThread();private final World world;private final List<Cell> sources;private final Integer ground;private final int nodeLimit,maxCost,deep;private final ToIntFunction<Cell> cost;private final LinkedHashMap<Cell,Integer> index=new LinkedHashMap<>();private final List<Cell> cells=new ArrayList<>();private final List<List<Integer>> adjacency=new ArrayList<>();private final List<Boolean> sinks=new ArrayList<>(),expanded=new ArrayList<>();private final Set<Cell> terminal=new HashSet<>();private int head,phase,total,found=-1;private int[] capacity,residual,back,sinkFlow;private final Map<Long,Integer> edgeFlow=new HashMap<>();private final SortedSet<Integer> sourceSet=new TreeSet<>();private LinkedHashMap<Integer,Integer> parent;private ArrayDeque<Integer> queue;private boolean diving=true,done;private Plan result;
        public CutJob(World world,Collection<Cell> support,Integer ground,int nodeLimit,int maxCost,ToIntFunction<Cell> cost){this.world=world;this.ground=ground;this.nodeLimit=nodeLimit;this.maxCost=maxCost;this.cost=cost==null?c->digCost(world,c,ground):cost;deep=ground==null?239:ground+3;sources=List.copyOf(new LinkedHashSet<>(support));for(var c:sources)if(!ground(c)&&world.solid(c)){index.put(c,cells.size());cells.add(c);}done=cells.isEmpty();}
        boolean ground(Cell c){return c.z()>238||c.z()>=deep;}static long edge(int a,int b){return (long)a<<32|(b&0xffff_ffffL);}int flow(int a,int b){return edgeFlow.getOrDefault(edge(a,b),0);}
        public boolean done(){return done;}public Plan result(){return result;}public int explored(){return cells.size();}
        public boolean advance(int work){if(Thread.currentThread()!=owner)throw new IllegalStateException("Structural search outside owner");while(!done&&work-->0){if(phase==0){if(head>=cells.size()){if(sinks.stream().noneMatch(Boolean::booleanValue)){done=true;break;}capacity=new int[cells.size()];head=0;phase=1;continue;}var c=cells.get(head);var neighbors=new ArrayList<Integer>();boolean sink=false;if(cells.size()>=nodeLimit){sink=true;expanded.add(false);}else{expanded.add(true);for(var d:NEIGHBORS){var next=new Cell(c.x()+d.x(),c.y()+d.y(),c.z()+d.z());if(next.x()<0||next.x()>=512||next.y()<0||next.y()>=512||next.z()<0)continue;var known=index.get(next);if(known!=null){neighbors.add(known);continue;}if(terminal.contains(next)){sink=true;continue;}if(!world.solid(next))continue;if(ground(next)){terminal.add(next);sink=true;continue;}neighbors.add(cells.size());index.put(next,cells.size());cells.add(next);}}adjacency.add(neighbors);sinks.add(sink);head++;}
            else if(phase==1){if(head<cells.size()){capacity[head]=Math.max(1,cost.applyAsInt(cells.get(head)));head++;}else{for(var c:sources){var i=index.get(c);if(i!=null){sourceSet.add(i);capacity[i]=INF;}}head=0;phase=2;}}
            else if(phase==2){if(head<cells.size()){int i=head++;if(expanded.get(i))for(int j:adjacency.get(i))if(!expanded.get(j))adjacency.get(j).add(i);}else{residual=capacity.clone();back=new int[cells.size()];sinkFlow=new int[cells.size()];beginPath();phase=3;}}
            else if(phase==3){if(queue.isEmpty()){if(diving){diving=false;beginPath();continue;}finishCut();continue;}int n=diving?queue.removeLast():queue.removeFirst(),i=n/2,side=n%2;if(side==0){if(diving){for(int j:adjacency.get(i))if(flow(j,i)>0)add(2*j+1,n);if(residual[i]>0)add(2*i+1,n);}else{if(residual[i]>0)add(2*i+1,n);for(int j:adjacency.get(i))if(flow(j,i)>0)add(2*j+1,n);}}else{if(sinks.get(i)){found=n;augment();continue;}if(back[i]>0)add(2*i,n);if(diving){int depth=cells.get(i).z();for(boolean lower:new boolean[]{false,true})for(int j:adjacency.get(i))if((cells.get(j).z()>depth)==lower)add(2*j,n);}else for(int j:adjacency.get(i))add(2*j,n);}}}return done;}
        void add(int node,int from){if(!parent.containsKey(node)){parent.put(node,from);queue.addLast(node);}}
        void beginPath(){parent=new LinkedHashMap<>();queue=new ArrayDeque<>();for(int i:sourceSet){parent.put(2*i,-1);queue.add(2*i);}found=-1;}
        void augment(){int bottleneck=INF,node=found;while(parent.get(node)!=-1){int prev=parent.get(node),pi=prev/2,ps=prev%2,ni=node/2,ns=node%2;if(ps==0&&ns==1&&pi==ni)bottleneck=Math.min(bottleneck,residual[pi]);else if(ps==1&&ns==0&&pi==ni)bottleneck=Math.min(bottleneck,back[pi]);else if(ps==0&&ns==1)bottleneck=Math.min(bottleneck,flow(ni,pi));node=prev;}bottleneck=Math.min(bottleneck,maxCost+1-total);node=found;sinkFlow[found/2]+=bottleneck;while(parent.get(node)!=-1){int prev=parent.get(node),pi=prev/2,ps=prev%2,ni=node/2,ns=node%2;if(ps==0&&ns==1&&pi==ni){residual[pi]-=bottleneck;back[pi]+=bottleneck;}else if(ps==1&&ns==0&&pi==ni){back[pi]-=bottleneck;residual[pi]+=bottleneck;}else if(ps==0&&ns==1)edgeFlow.put(edge(ni,pi),flow(ni,pi)-bottleneck);else edgeFlow.put(edge(pi,ni),flow(pi,ni)+bottleneck);node=prev;}total+=bottleneck;if(total>maxCost)done=true;else beginPath();}
        void finishCut(){var cut=new ArrayList<Cell>();int value=0,falling=0;for(int i=0;i<cells.size();i++)if(parent.containsKey(2*i)){falling++;if(!parent.containsKey(2*i+1)){cut.add(cells.get(i));value+=capacity[i];}}done=true;if(cut.isEmpty())return;cut.sort(CELLS);result=new Plan(sources,cut,clawSites(cut,world),value,Math.max(0,falling-cut.size()),cells.size());}
    }
    static int chebyshev(Cell a,Cell b){return Math.max(Math.max(Math.abs(a.x()-b.x()),Math.abs(a.y()-b.y())),Math.abs(a.z()-b.z()));}
    public static List<Cell> clawSites(Collection<Cell> cut,World world){var remaining=new HashSet<>(cut);var candidates=remaining.stream().filter(c->{if(world==null)return true;for(var d:FACES)if(!world.solid(c.x()+d[0],c.y()+d[1],c.z()+d[2]))return true;return false;}).sorted(CELLS).toList();var sites=new ArrayList<Cell>();while(!remaining.isEmpty()){var pool=candidates.stream().filter(c->remaining.stream().anyMatch(o->chebyshev(c,o)<=1)).toList();if(pool.isEmpty())pool=remaining.stream().sorted(CELLS).toList();Cell best=null;int count=-1;for(var c:pool){int value=(int)remaining.stream().filter(o->chebyshev(c,o)<=1).count();if(value>count||value==count&&(best==null||c.z()>best.z())){best=c;count=value;}}sites.add(best);var chosen=best;remaining.removeIf(o->chebyshev(o,chosen)<=1);}return List.copyOf(sites);}
    public static boolean fallsAfter(World world,Collection<Cell> removed,Collection<Cell> support,int limit){var gone=new HashSet<>(removed);var starts=support.stream().filter(c->!gone.contains(c)&&world.solid(c)).toList();if(starts.isEmpty())return true;var seen=new HashSet<>(starts);var stack=new ArrayDeque<>(starts);while(!stack.isEmpty()){var c=stack.removeLast();if(c.z()>238||seen.size()>limit)return false;for(var d:NEIGHBORS){var next=new Cell(c.x()+d.x(),c.y()+d.y(),c.z()+d.z());if(!seen.contains(next)&&next.z()>=0&&!gone.contains(next)&&world.solid(next)){seen.add(next);stack.add(next);}}}return true;}
}
